from toolz import partition_all, take
from toolz.curried import partition_all as cpartition_all

# curried version still works + raises on broken
class Broken:
    def __init__(self, d, fl): self._d=list(d); self._fl=fl
    def __iter__(self): return iter(self._d)
    def __len__(self): return self._fl

print('curried correct:', list(cpartition_all(3)(range(5))))
try:
    list(cpartition_all(4, Broken(range(1,8), 5)))
    print('curried broken: NO RAISE (bad)')
except LookupError:
    print('curried broken: LookupError (good)')

# laziness: taking only first chunk should NOT raise even if len is broken
g = partition_all(4, Broken(range(1,8), 5))
print('take(1, broken):', list(take(1, g)))  # should yield first chunk, no error yet

# __len__ raising non-TypeError (e.g. RuntimeError) must propagate, not be swallowed
class WeirdLen:
    def __iter__(self): return iter([1,2,3,4,5])
    def __len__(self): raise RuntimeError('boom')
try:
    list(partition_all(4, WeirdLen()))
    print('WeirdLen: no exc (unexpected)')
except RuntimeError:
    print('WeirdLen: RuntimeError propagated (good)')
except LookupError:
    print('WeirdLen: LookupError (bad - should propagate RuntimeError)')

# sequence with __len__ that returns non-int is rejected by len() (TypeError) -> treated as no len
class NonIntLen:
    def __iter__(self): return iter([1,2,3,4,5])
    def __len__(self): return 'five'
try:
    print('NonIntLen:', list(partition_all(4, NonIntLen())))
except TypeError:
    print('NonIntLen: TypeError (len enforces int) -> falls back, ok')
"

